const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const slides=[
 ['◎','先定国家，<br><em>再一起挑城市。</em>','一个国家里，可能藏着好几座舍不得错过的城。先选出想停留的地方；去过哪里，也请告诉我们。'],
 ['↗','想去的城市，<br><em>以怎样的顺序抵达？</em>','想先走进热闹的城市，还是把海边留到最后？这一轮决定抵达的顺序，以及每座城值得停留几天。'],
 ['✳','到了每座城，<br><em>把时间留给什么？</em>','也许是一座美术馆、一片海，或一条想慢慢走的街。这一轮挑出心愿，之后再核对位置与开放时间。'],
 ['☼','从清晨到夜晚，<br><em>每一天会怎样展开？</em>','城市、顺序与想看的地方都确定后，再看它们如何落进每天的安排。想法变了，也随时可以返回调整。']
];
const suggestions={日本:['东京','京都','大阪','奈良','箱根','札幌'],法国:['巴黎','里昂','尼斯','波尔多'],意大利:['罗马','佛罗伦萨','威尼斯','米兰'],希腊:['雅典','圣托里尼','米科诺斯'],土耳其:['伊斯坦布尔','卡帕多奇亚','安塔利亚']};
const sights={东京:['浅草寺','上野公园','涩谷街区'],京都:['伏见稻荷大社','清水寺','岚山'],大阪:['大阪城','道顿堀'],巴黎:['埃菲尔铁塔','卢浮宫','蒙马特'],罗马:['斗兽场','万神殿'],佛罗伦萨:['圣母百花大教堂','乌菲兹美术馆'],威尼斯:['圣马可广场','大运河'],雅典:['雅典卫城','普拉卡老城'],圣托里尼:['伊亚小镇','费拉步道'],伊斯坦布尔:['圣索菲亚大教堂','蓝色清真寺'],卡帕多奇亚:['格雷梅露天博物馆','热气球体验']};
const state={round:0,slide:0,cities:[],days:{},sights:{}}, form=$('#trip-form');
function go(n){state.round=n;document.querySelectorAll('.round-panel').forEach(p=>p.hidden=Number(p.dataset.round)!==n);document.querySelectorAll('.track-item').forEach(p=>p.classList.toggle('active',Number(p.dataset.track)===n));if(n===2)route();if(n===3)attractions();if(n===4)days();$('#planner').scrollIntoView({behavior:'smooth'});}
function slide(n){state.slide=Math.max(0,Math.min(3,n));const [icon,title,description]=slides[state.slide];$('#slide-index').textContent=`0${state.slide+1} / 04`;$('#slide-icon').textContent=icon;$('#slide-title').innerHTML=title;$('#slide-description').textContent=description;$('#slide-dots').innerHTML=slides.map((_,i)=>`<button type="button" data-slide="${i}" class="${i===state.slide?'active':''}" aria-label="查看第 ${i+1} 步"></button>`).join('');$('#slide-prev').disabled=state.slide===0;$('#slide-next').disabled=state.slide===3;}
const slidePhotos=['photo-1493976040374-85c8e12f0c0e','photo-1502602898657-3e91760cbb34','photo-1560703649-e3055f28bcf8','photo-1570939274717-7eda259b50ed'];
const originalSlide=slide;
slide=function(n){originalSlide(n);$('.intro-visual').style.backgroundImage=`linear-gradient(180deg,rgba(7,28,38,.05),rgba(7,28,38,.42)),url('https://images.unsplash.com/${slidePhotos[state.slide]}?w=1100&q=85')`;};
function cities(){const country=$('#country').value.trim(),list=suggestions[country]||[];$('#city-help').textContent=list.length?`在${country}，你想为哪几座城市停下脚步？选一选，也可以自己添加。`:'先写下你想去的城市。更多目的地建议会在后续版本加入。';$('#city-options').innerHTML=list.map(c=>`<button type="button" class="city-chip ${state.cities.includes(c)?'selected':''}" data-city-option="${esc(c)}" aria-pressed="${state.cities.includes(c)}">${esc(c)} <span>${state.cities.includes(c)?'✓':'＋'}</span></button>`).join('');$('#selected-cities').textContent=state.cities.length?state.cities.join(' → '):'还未选择';}
function addCity(c){c=c.trim();if(c&&!state.cities.includes(c))state.cities.push(c);cities();}
function total(){const sum=state.cities.reduce((a,c)=>a+(Number(state.days[c])||2),0),wanted=Number(new FormData(form).get('duration'));$('#route-total').textContent=`这些城市打算停留 ${sum} 天${wanted?` · 第一轮预计约 ${wanted} 天`:''}。别忘了为跨城交通和抵离留出时间。`;}
function route(){const b=new FormData(form);$('#route-context').innerHTML=`<span>目的地：<b>${esc(b.get('country'))}</b></span><span>从 ${esc(b.get('departure'))} 出发</span><span>${esc(b.get('travelers'))} 人同行</span>`;$('#route-list').innerHTML=state.cities.map((c,i)=>`<div class="route-row"><span class="route-node">${String(i+1).padStart(2,'0')}</span><div class="route-city"><strong>${esc(c)}</strong><small>${i?'从 '+esc(state.cities[i-1])+' 前往':'从这里开始'}</small></div><label>停留 <input type="number" min="1" max="20" data-days="${esc(c)}" value="${state.days[c]||2}"> 天</label><div class="route-move"><button type="button" data-move="up" data-index="${i}" aria-label="${esc(c)}上移" ${i===0?'disabled':''}>↑</button><button type="button" data-move="down" data-index="${i}" aria-label="${esc(c)}下移" ${i===state.cities.length-1?'disabled':''}>↓</button></div></div>`).join('');total();}
function attractions(){$('#attraction-list').innerHTML=state.cities.map(c=>{const chosen=state.sights[c]||[],list=sights[c]||['城市地标','当地美食','街区漫步','自然景观'];return `<div class="attraction-city"><div class="attraction-city-heading"><span>✳</span><div><h4>${esc(c)}</h4><p>想在这里待 ${state.days[c]||2} 天 · 挑一挑想看的地方</p></div></div><div class="attraction-options">${list.map(s=>`<label><input type="checkbox" data-attraction-city="${esc(c)}" value="${esc(s)}" ${chosen.includes(s)?'checked':''}><span>${esc(s)}</span></label>`).join('')}</div><div class="add-row"><input type="text" data-custom-attraction="${esc(c)}" placeholder="还有什么让你想为这座城停留？"><button type="button" class="outline-button" data-add-attraction="${esc(c)}">添加 ＋</button></div>${chosen.filter(s=>!list.includes(s)).map(s=>`<span class="custom-tag">${esc(s)} <button type="button" data-remove-attraction="${esc(c)}" data-value="${esc(s)}" aria-label="移除${esc(s)}">×</button></span>`).join('')}</div>`}).join('');}
function days(){const b=new FormData(form);$('#summary-bar').innerHTML=`<span><b>${esc(b.get('country'))}</b> · ${state.cities.length} 座城市</span><span>${esc(b.get('travelers'))} 人同行</span><span>去过：${esc(b.get('visited')||'未填写')}</span>`;let d=0;$('#day-list').innerHTML=state.cities.map(c=>Array.from({length:Number(state.days[c])||2},(_,i)=>{d++;const list=state.sights[c]||[],s=list.length?list[i%list.length]:'';return `<article class="day-row"><div class="day-number">DAY ${String(d).padStart(2,'0')}</div><div><h4>${esc(c)} · ${i===0?'初见这座城':'在这里多待一天'}</h4><p>${s?'想去看看：'+esc(s)+'。':'这一天想看什么，可以在上一轮补充。'}${i===0&&d>1?' 这天还要为跨城移动留出时间。':''}</p></div><span class="day-tag">结构示意</span></article>`}).join('')).join('');}
$('#slide-prev').onclick=()=>slide(state.slide-1);$('#slide-next').onclick=()=>slide(state.slide+1);$('#slide-dots').onclick=e=>{const b=e.target.closest('[data-slide]');if(b)slide(Number(b.dataset.slide))};$('#begin-planning').onclick=()=>go(1);document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(Number(b.dataset.go)));
$('#country').oninput=cities;$('#city-options').onclick=e=>{const b=e.target.closest('[data-city-option]');if(!b)return;const c=b.dataset.cityOption;state.cities=state.cities.includes(c)?state.cities.filter(x=>x!==c):[...state.cities,c];cities()};$('#add-city').onclick=()=>{addCity($('#custom-city').value);$('#custom-city').value=''};$('#custom-city').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('#add-city').click()}};document.querySelectorAll('[data-city]').forEach(b=>b.onclick=()=>{$('#country').value=b.dataset.country;addCity(b.dataset.city);go(1)});
form.onsubmit=e=>{e.preventDefault();if(!form.reportValidity())return;if(!state.cities.length){$('#city-help').textContent='先选一座想停留的城市，我们再继续安排路上的顺序。';$('#city-options').scrollIntoView({behavior:'smooth',block:'center'});return}go(2)};
$('#route-list').onclick=e=>{const b=e.target.closest('[data-move]');if(!b)return;const i=Number(b.dataset.index),j=i+(b.dataset.move==='up'?-1:1);if(j<0||j>=state.cities.length)return;[state.cities[i],state.cities[j]]=[state.cities[j],state.cities[i]];route()};$('#route-list').onchange=e=>{if(!e.target.matches('[data-days]'))return;state.days[e.target.dataset.days]=Math.max(1,Math.min(20,Number(e.target.value)||1));e.target.value=state.days[e.target.dataset.days];total()};$('#confirm-route').onclick=()=>{document.querySelectorAll('[data-days]').forEach(el=>state.days[el.dataset.days]=Math.max(1,Math.min(20,Number(el.value)||1)));go(3)};
$('#attraction-list').onchange=e=>{if(!e.target.matches('[data-attraction-city]'))return;const c=e.target.dataset.attractionCity,list=state.sights[c]||[];state.sights[c]=e.target.checked?[...new Set([...list,e.target.value])]:list.filter(x=>x!==e.target.value)};$('#attraction-list').onclick=e=>{const add=e.target.closest('[data-add-attraction]');if(add){const c=add.dataset.addAttraction,input=[...document.querySelectorAll('[data-custom-attraction]')].find(x=>x.dataset.customAttraction===c),v=input.value.trim();if(v){state.sights[c]=[...new Set([...(state.sights[c]||[]),v])];attractions()}return}const rm=e.target.closest('[data-remove-attraction]');if(rm){const c=rm.dataset.removeAttraction;state.sights[c]=(state.sights[c]||[]).filter(x=>x!==rm.dataset.value);attractions()}};$('#confirm-attractions').onclick=()=>go(4);
slide(0);cities();
$('#hero-quick-start').onsubmit=e=>{e.preventDefault();const country=$('#hero-country').value.trim();if(country){$('#country').value=country;cities();}go(0);};
